 let twoPartBrief=$('twopart-brief');if(k==='twopart'&&!legacyTwoPartM){if(!twoPartBrief){twoPartBrief=document.createElement('section');twoPartBrief.id='twopart-brief';twoPartBrief.setAttribute('aria-label','两部收费题设与当前账目');twoPartBrief.innerHTML='<p class="reading"><strong>题设：</strong>阿姨只面对一位顾客。顾客对第 q 杯的愿付价格 P(q)=10−q，阿姨总成本 C(q)=2q+0.25q²；先交一次入场费 A，再按每杯价格 p 付款。数字和豆浆场景是自主举例，数量按连续量简化。</p><p class="reading"><strong>这道题在问：</strong>入场费多高顾客才愿意来？阿姨把每杯价格定在什么位置，才能连同入场费赚得最多？</p><p class="reading"><strong>现在看什么：</strong><span id="twopart-live"></span></p><p class="reading"><strong>当前账目：</strong><span id="twopart-account"></span></p>';$('legend').before(twoPartBrief)}const f=lastM,r=f.r,n=x=>fmtM(x);$('twopart-live').textContent=plot.dataset.filmNarration;$('twopart-account').textContent=`每杯标价${n(f.p)}元，入场费${n(r.A)}元；若参加会买${n(r.demandBeforeFee)}杯，入场前剩余${n(r.surplus)}元。${r.accepted?'顾客进店，':'顾客不进店，'}实际买${n(r.q)}杯，阿姨利润${n(r.profit)}元，顾客最终净好处${n(r.consumerUtility)}元。`; }else twoPartBrief?.remove();

