 let nonlinearBrief=$('nonlinear-brief');if(k==='nonlinear'&&!legacyNonlinearM){if(!nonlinearBrief){nonlinearBrief=document.createElement('section');nonlinearBrief.id='nonlinear-brief';nonlinearBrief.setAttribute('aria-label','非线性定价的题设和当前账目');nonlinearBrief.innerHTML='<p class="reading"><strong>题设：</strong>两位顾客各自最多买两杯豆浆，也可以不买。阿姨制作零成本，认不出顾客类型，只能给所有人同一张价格单；一杯价和第二杯追加价可以不同。两组估值为自主构造；顾客无差异时选使阿姨收入较高的选项。</p><p class="reading"><strong>这道题在问：</strong>怎样定价最赚钱？第二杯最优价格会比第一杯便宜，也会比它贵吗？</p><p class="reading"><strong>现在看什么：</strong><span id="nonlinear-live"></span></p><p class="reading"><strong>当前两位顾客的总估值：</strong><span id="nonlinear-values"></span></p><p class="reading"><strong>当前选择与净好处：</strong><span id="nonlinear-choice"></span></p>';$('legend').before(nonlinearBrief)}const f=lastM,n=x=>fmtM(x),choice=person=>{const labels=['不买','一杯','两杯'],names=person.tied.map(i=>labels[i]).join('、');return `${labels[person.chosen]}（不买${n(person.utilities[0])}，一杯${n(person.utilities[1])}，两杯${n(person.utilities[2])}元${person.tied.length>1?'；'+names+'同样好，按约定选支付较多者':''}）`};$('nonlinear-live').textContent=plot.dataset.filmNarration;$('nonlinear-values').textContent=`爱喝者：一杯${n(f.values.H[1])}、两杯${n(f.values.H[2])}元；另一位：一杯${n(f.values.L[1])}、两杯${n(f.values.L[2])}元。`;$('nonlinear-choice').textContent=`爱喝者选${choice(f.outcome.H)}；另一位选${choice(f.outcome.L)}。`;}else nonlinearBrief?.remove();

